function readPrefs(){try{return JSON.parse(localStorage.getItem('rasad-demo')||'null');}catch{return null;}}
let demoPrefs=readPrefs() || {settings:{scope:'selected',interval:60,retention:7,domains_enabled:true},enabled:[0,1,2,4,7],audit:[]};
function demoSave(){localStorage.setItem('rasad-demo',JSON.stringify(demoPrefs));}
function demoReport(){
 const now=Math.floor(Date.now()/1000),midnight=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Tehran'}));midnight.setHours(0,0,0,0);const start=Math.floor(midnight.getTime()/1000);
 const factor={today:1,yesterday:.82,week:5.7,month:18.4}[state.period];
 const users=demoNames.map((name,i)=>({email:demoEmails[i],name,inbound:i<7?'Reality · 443':'VLESS · 8443',protocol:'vless',enabled:i!==10,online:i<7,up:(i+1)*.23*2**30,down:(12-i)*5.3*2**30,total:(i%3?80:120)*2**30,expiry:(now+(i+7)*86400)*1000,consent:demoPrefs.enabled.includes(i),selected:demoPrefs.enabled.includes(i),monitored:demoPrefs.settings.domains_enabled&&demoPrefs.enabled.includes(i),period_up:(.22+i*.043)*factor*2**30,period_down:(18.1-i*1.21)*factor*2**30}));
 const base=[['youtube.com',.39,824],['instagram.com',.25,638],['google.com',.11,412],['telegram.org',.10,297],['github.com',.09,186],['spotify.com',.06,128]];
 const perUser=users.map((u,j)=>{
  if(!u.monitored)return [];
  const down=u.period_down*.91,up=u.period_up*.91,known=.87;
  return [...base.map(([domain,w,n],i)=>({domain,up:Math.round(up*known*w),down:Math.round(down*known*w),connections:Math.round(n*factor*(.10+j*.009)),last:now-i*360,source:'dispatcher_counter'})),{domain:'__unknown_tcp__',up:Math.round(up*.04),down:Math.round(down*.04),connections:16,last:now-45,source:'dispatcher_counter'},{domain:'__unknown_udp__',up:Math.round(up*.09),down:Math.round(down*.09),connections:22,last:now-20,source:'dispatcher_counter'}].map(d=>({...d,bytes:d.up+d.down}));
 });
 users.forEach((u,i)=>u.destination_summary=summarizeDestinations(perUser[i]));
 const selected=state.user?users.findIndex(u=>u.email===state.user):-1,source=selected>=0?perUser[selected]:perUser.flat();
 const merged=new Map();for(const row of source){const cur=merged.get(row.domain)||{...row,up:0,down:0,bytes:0,connections:0};for(const k of ['up','down','bytes','connections'])cur[k]+=row[k];cur.last=Math.max(cur.last,row.last);merged.set(row.domain,cur);}
 const domains=[...merged.values()].sort((a,b)=>b.bytes-a.bytes),summary=summarizeDestinations(domains);
 const weights=Array.from({length:24},(_,i)=>.3+Math.sin(i*.4)**2+(i>17?1.6:0)),sum=weights.reduce((a,b)=>a+b,0);
 const series=weights.map((w,i)=>({bucket:start+i*3600,down:summary.measured_down*w/sum,up:summary.measured_up*w/sum,supported_bytes:summary.supported_bytes*w/sum,unknown_bytes:summary.unknown_bytes*w/sum}));
 return {mode:'demo',users,domains,destination_summary:summary,destination_series:series,series,period:state.period,start,end:now,last_sync:now,started:now-8*86400,settings:demoPrefs.settings,error:null,log_status:'disabled',collector:{cycle_ms:24,api_bytes:428001,api_calls:46,log_budget:524288},timezone:'Asia/Tehran',audit:demoPrefs.audit,metrics_status:'ready',module:{status:'ready',last_snapshot:now,snapshot_age:0,dropped_flows:0,byte_basis:'dispatcher_payload',first_snapshot_is_baseline:false}};
}
function unknownDestination(domain){return domain.startsWith('__unknown_')||domain.startsWith('__overflow_');}
function summarizeDestinations(rows){
 const measured=rows.filter(d=>d.bytes!=null),known=measured.filter(d=>!unknownDestination(d.domain)),unknown=measured.filter(d=>unknownDestination(d.domain));
 const sum=(list,key)=>list.reduce((n,d)=>n+(d[key]||0),0);
 const total=sum(measured,'bytes'),supported=sum(known,'bytes');
 return {measured_up:sum(measured,'up'),measured_down:sum(measured,'down'),measured_bytes:total,supported_up:sum(known,'up'),supported_down:sum(known,'down'),supported_bytes:supported,unknown_up:sum(unknown,'up'),unknown_down:sum(unknown,'down'),unknown_bytes:sum(unknown,'bytes'),supported_domains:known.length,connections:sum(measured,'connections'),attribution_ratio:total?supported/total:null};
}
function destinationSummary(){return state.report.destination_summary||summarizeDestinations(state.report.domains);}
function siteRows(){return state.report.domains.filter(d=>d.bytes!=null&&!unknownDestination(d.domain));}
function hasMeasurement(){return state.report.module?.status==='ready'||state.report.metrics_status==='ready'||destinationSummary().measured_bytes>0;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function api(path,data){
 const requestEpoch=loadEpoch;
 const opts={credentials:'same-origin',headers:{}};
 if(data!==undefined){opts.method='POST';opts.headers={'Content-Type':'application/json','X-CSRF-Token':state.csrf};opts.body=JSON.stringify(data);}
 const response=await fetch('/api/'+path,opts);
 if(response.status===401){if(path!=='login'&&requestEpoch===loadEpoch)loginScreen();throw new Error(path==='login'?'نام کاربری یا رمز عبور درست نیست.':'برای ادامه وارد شوید.');}
 if(!response.ok)throw new Error(response.status===429?'تلاش‌های زیاد؛ پنج دقیقه دیگر دوباره امتحان کنید.':'درخواست انجام نشد. اتصال و تنظیمات را بررسی کنید.');
 return response.json();
}
function reportKey(period=state.period,user=state.user){return JSON.stringify([period,user]);}
function load(){
 if(state.reportSelection!==reportKey()){state.report=null;state.reportSelection=null;}
 loadVersion++;
 if(state.busy)return loadPromise;
 state.busy=true;
 loadPromise=Promise.resolve().then(async()=>{
  let version;
  try{
   do{
    version=loadVersion;
    const period=state.period,user=state.user,epoch=loadEpoch;
    const current=()=>version===loadVersion&&period===state.period&&user===state.user&&epoch===loadEpoch;
    try{
     const report=state.mode==='demo'?demoReport():await api(`report?period=${period}${user?'&email='+encodeURIComponent(user):''}`);
     if(!current())continue;
     state.report=report;state.reportSelection=reportKey(period,user);render();
    }
    catch(e){if(!current())continue;toast(e.message);if(!state.report&&state.mode==='live'&&!$('.login'))$('#app').innerHTML=`<div class="login"><div class="card"><h1>اتصال برقرار نشد</h1><p>سرویس رصد در دسترس نیست. داده‌های واقعی هنوز دریافت نشده‌اند.</p><button class="btn primary" data-action="refresh">تلاش دوباره</button></div></div>`;}
   }while(version!==loadVersion);
  }
  finally{state.busy=false;loadPromise=null;}
 });
 return loadPromise;
}
function audit(action,target='server'){demoPrefs.audit.unshift({id:Date.now(),ts:Math.floor(Date.now()/1000),action,target});demoPrefs.audit=demoPrefs.audit.slice(0,60);demoSave();}
async function mutate(path,data){if(state.mode==='live')return api(path,data);if(path==='settings'){demoPrefs.settings=data;audit('settings_saved');}if(path==='monitor'){const i=demoEmails.indexOf(data.email);demoPrefs.enabled=demoPrefs.enabled.filter(x=>x!==i);if(data.enabled)demoPrefs.enabled.push(i);audit(data.enabled?'monitor_on':'monitor_off_and_erased',data.email);}if(path==='monitor-all'){demoPrefs.enabled=data.enabled?demoEmails.map((_,i)=>i):[];audit(data.enabled?'monitor_all_current_on':'monitor_all_off_and_erased');}demoSave();}
